#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    // We compute inclusive reverse prefix sums:
    // output[i] = x[i] + x[i+1] + ... + x[n-1]
    //
    // Do it via a parallel "prefix" on the reversed index:
    // Let y[j] = x[n-1-j]. Then prefix_y[j] = sum_{k=0..j} y[k]
    // output[i] = prefix_y[n-1-i].

    int numThreads = 1;
    std::vector<long long> threadSums; // per-thread partial sums of y-chunks

    #pragma omp parallel
    {
        #pragma omp single
        {
            numThreads = omp_get_num_threads();
            threadSums.assign(numThreads, 0LL);
        }

        const int tid = omp_get_thread_num();

        // Partition j in [0, n) among threads (static partition, contiguous chunks)
        const int base = n / numThreads;
        const int rem  = n % numThreads;
        const int start = tid * base + (tid < rem ? tid : rem);
        const int len   = base + (tid < rem ? 1 : 0);
        const int end   = start + len;

        // Phase 1: local prefix within chunk in terms of j, write directly to output.
        // For each j, i = n-1-j.
        long long local = 0;
        for (int j = start; j < end; ++j) {
            local += static_cast<long long>(x[n - 1 - j]);
            output[n - 1 - j] = static_cast<int>(local); // temporary: missing offset from earlier chunks
        }
        threadSums[tid] = local;

        #pragma omp barrier

        // Phase 2: compute offset = sum of threadSums for all threads with id < tid.
        // Use a single thread to form exclusive prefix of threadSums in-place.
        #pragma omp single
        {
            long long running = 0;
            for (int t = 0; t < numThreads; ++t) {
                const long long tmp = threadSums[t];
                threadSums[t] = running; // exclusive offset for thread t
                running += tmp;
            }
        }

        #pragma omp barrier

        // Phase 3: add the per-thread offset to all elements in this chunk.
        const long long offset = threadSums[tid];
        if (offset != 0) {
            for (int j = start; j < end; ++j) {
                const int i = n - 1 - j;
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
            }
        }
    }
}
